/**
 * Retrieve an asset by its semantic ID (e.g. 'characters.full.gettingReady' or 'char-full-getting-ready').
 * Throws an explicit error if the asset does not exist.
 */
export function getAsset(id: string): AssetDefinition {
  const asset = ASSETS_BY_ID[id];
  if (!asset) {
    const parts = id.split('.');
    let current: any = assets;
    for (const part of parts) {
      if (current && typeof current === 'object' && part in current) {
        current = current[part];
      } else {
        current = undefined;
        break;
      }
    }
    if (current && current.src) {
      return current as AssetDefinition;
    }
    throw new Error(`[AssetRegistry] Asset not found for identifier: "${id}". Known IDs: ${ASSET_MANIFEST.length} available.`);
  }
  return asset;
}

/**
 * Safely retrieve an asset by identifier without throwing.
 */
export function tryGetAsset(id: string): AssetDefinition | undefined {
  try {
    return getAsset(id);
  } catch {
    return undefined;
  }
}

/**
 * Check if an asset identifier exists in the registry.
 */
export function hasAsset(id: string): boolean {
  return tryGetAsset(id) !== undefined;
}

/**
 * Retrieve all assets designated for initial preload (Scene 01 + opening foundations).
 */
export function getPreloadAssets(): AssetDefinition[] {
  return ASSET_MANIFEST.filter(a => a.preload);
}

/**
 * Retrieve all assets belonging to a given category.
 */
export function getAssetsByCategory(category: AssetCategory): AssetDefinition[] {
  return ASSET_MANIFEST.filter(a => a.category === category);
}

/**
 * Retrieve all assets mapped to a given narrative Scene.
 */
export function getAssetsByScene(sceneId: SceneId): AssetDefinition[] {
  return ASSET_MANIFEST.filter(a => a.sceneIds.includes(sceneId));
}
